func (d Hospital) esV3()                      {}
func (d Hospital) CodigoDocumentoSector() int { return 17 }
func (d Hospital) TipoFacturaDocumento() int  { return 1 }
func (d Hospital) Informacion() Info {
	h := d.Cabecera
	return Info{Nit: h.NitEmisor, Numero: h.NumeroFactura, CUF: h.Cuf, CUFD: h.Cufd, CodigoInterno: h.CodigoInterno, Sucursal: int(h.CodigoSucursal), POS: int(h.CodigoPuntoVenta.OrZero()), Fecha: h.FechaEmision.Time(), Sector: 17, Tipo: 1}
}
func (d Hospital) Validar() error {
	if err := validarInfo(d.Informacion()); err != nil {
		return err
	}
	if d.Cabecera.CodigoDocumentoSector != 17 {
		return fmt.Errorf("sector de cabecera distinto de 17")
	}
	if len(d.Detalle) == 0 || len(d.Detalle) > 500 {
		return fmt.Errorf("el documento requiere entre 1 y 500 detalles")
	}
	if err := d.Cabecera.validarXSD(); err != nil {
		return fmt.Errorf("cabecera: %w", err)
	}
	for n, detail := range d.Detalle {
		if err := detail.validarXSD(); err != nil {
			return fmt.Errorf("detalle %d: %w", n+1, err)
		}
	}
	return nil
}
func (d Hospital) MarshalXML(e *xml.Encoder, start xml.StartElement) error {
	start.Name = xml.Name{Local: "facturaElectronicaHospitalClinica"}
	start.Attr = append(start.Attr, xml.Attr{Name: xml.Name{Local: "xmlns:xsi"}, Value: xsi}, xml.Attr{Name: xml.Name{Local: "xsi:noNamespaceSchemaLocation"}, Value: "facturaElectronicaHospitalClinica.xsd"})
	type payload Hospital
	return e.EncodeElement(payload(d), start)
}

